export function createSubtitleFromTemplate({
	template,
	startTime = 0,
}: {
	template: SubtitleTemplate;
	startTime?: number;
}): Omit<TextElement, "id"> {
	const {
		templateId: _templateId,
		templateName: _templateName,
		...elementProps
	} = template;
	return {
		...elementProps,
		duration: TIMELINE_CONSTANTS.DEFAULT_ELEMENT_DURATION,
		startTime,
		trimStart: 0,
		trimEnd: 0,
	};
}
